package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.stream.Stream;
import java.util.zip.ZipInputStream;
import org.jlinalg.singlecell.SoupXAmbient;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.MethodSource;
import static org.junit.jupiter.api.Assertions.*;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;

class SoupXWorkflowTest {
    @TempDir static Path corpus;
    @TempDir Path temporary;
    static Map<String,byte[]> originals;
    record Context(Path root,SoupXWorkflowRequest.Request request,SoupXWorkflowInputs.Population population,long initialOperations){ }
    record Case(String version,String id){@Override public String toString(){return version+":"+id;}}
    static final Map<String,Context> contexts=new LinkedHashMap<>();
    @BeforeAll static void load()throws Exception{
        var files=new LinkedHashMap<String,byte[]>();try(var stream=new ZipInputStream(Objects.requireNonNull(SoupXWorkflowTest.class.getResourceAsStream("/org/jlinalg/singlecell/soupx-workflow/original-worker-transports-v1.zip")))){
            for(var entry=stream.getNextEntry();entry!=null;entry=stream.getNextEntry()){String name=entry.getName();NextflowFiles.member(name);byte[] bytes=stream.readNBytes(16<<20);assertTrue(bytes.length<(16<<20));assertNull(files.put(name,bytes));}
        }
        var index=object(parse(files.get("INDEX.json")));var expected=object(index.get("files"));assertEquals(286,expected.size());assertEquals(expected.size()+1,files.size());
        for(var e:expected.entrySet()){var value=object(e.getValue());byte[] bytes=Objects.requireNonNull(files.get(e.getKey()));assertEquals(integer(value.get("bytes"),0,16<<20),bytes.length);assertEquals(text(value.get("sha256")),NextflowFiles.sha(bytes));Path path=corpus.resolve(e.getKey()).normalize();assertTrue(path.startsWith(corpus));Files.createDirectories(path.getParent());Files.write(path,bytes,StandardOpenOption.CREATE_NEW);}
        originals=Collections.unmodifiableMap(files);
        for(String v:List.of("1.6.2","1.3.0")){Path root=corpus.resolve(v);var request=request(root,Map.of());var budget=new SoupXAmbient.Budget(request.auditOperations());var population=SoupXWorkflowInputs.validate(root.resolve("inputs"),request,budget);contexts.put(v,new Context(root,request,population,budget.used()));}
    }
    @AfterAll static void unchanged()throws IOException{for(var e:originals.entrySet())if(!e.getKey().equals("INDEX.json"))assertArrayEquals(e.getValue(),Files.readAllBytes(corpus.resolve(e.getKey())));}
    static Object parse(byte[] raw)throws IOException{return NextflowParameters.parse(NextflowFiles.utf8(raw),16<<20,3000000);}
    static Map<String,Object> json(Path path)throws IOException{return object(parse(Files.readAllBytes(path)));}
    static void save(Path path,Object value)throws IOException{Files.writeString(path,NextflowJson.json(value)+"\n",StandardCharsets.UTF_8);}
    static SoupXWorkflowRequest.Request request(Path root,Map<String,Object> changes)throws IOException{var raw=json(root.resolve("source-request.json"));raw.putAll(changes);return SoupXWorkflowRequest.parse(raw,root);}
    static Stream<String> versions(){return Stream.of("1.6.2","1.3.0");}
    static Stream<Case> cases(){return versions().flatMap(v->Stream.of("fixed-constant","fixed-per-cell","manual-provided","manual-estimated","auto-estimate","auto-adjust").map(id->new Case(v,id)));}
    static Map<String,Object> analysis(Context c,String id)throws IOException{for(var a:c.request.analyses())if(text(a.get("id")).equals(id))return a;throw new IOException("Missing case");}
    static SoupXWorkflowTransport.Meter meter(Context c)throws IOException{var meter=new SoupXWorkflowTransport.Meter(c.request.auditOperations());meter.spend(c.initialOperations);return meter;}
    static Map<String,Object> audit(Context c,Path target,String id)throws IOException{return SoupXWorkflowAudit.analysis(target,analysis(c,id),c.population,c.request,meter(c));}
    Path caseCopy(String version,String id)throws IOException{Path from=contexts.get(version).root.resolve("worker/cases").resolve(id),target=temporary.resolve(id);copy(from,target);return target;}
    static void copy(Path from,Path target)throws IOException{try(var paths=Files.walk(from)){for(Path p:paths.toList()){Path to=target.resolve(from.relativize(p));if(Files.isDirectory(p))Files.createDirectories(to);else Files.copy(p,to);}}}
    Path workerCopy(String version)throws IOException{Path from=contexts.get(version).root.resolve("worker"),target=temporary.resolve("worker");Files.createDirectory(target);try(var files=Files.list(from)){for(Path p:files.toList())if(Files.isRegularFile(p))Files.copy(p,target.resolve(p.getFileName()));}return target;}
    static void tableChange(Path path,String column,int row,String value,String kind)throws IOException{var data=json(path);var columns=list(data.get("columns"));int at=-1;for(int i=0;i<columns.size();i++){var c=object(columns.get(i));if(text(c.get("name")).equals(column)){at=i;replace(c.get("tokens"),row,value);if(kind!=null)replace(c.get("kinds"),row,kind);}}assertTrue(at>=0);save(path,data);Path tsv=path.resolveSibling(path.getFileName().toString().replaceFirst("[.]json$",".tsv"));var lines=new ArrayList<>(Files.readAllLines(tsv,StandardCharsets.UTF_8));String[] fields=lines.get(row+1).split("\t",-1);fields[at]=value;lines.set(row+1,String.join("\t",fields));Files.write(tsv,lines,StandardCharsets.UTF_8);}
    static void replace(Object raw,int at,Object value){assertInstanceOf(List.class,raw);@SuppressWarnings("unchecked") var values=(List<Object>)raw;values.set(at,value);}
    static void sparseChange(Path descriptor,String value,boolean coherent)throws IOException{var root=json(descriptor);Path part=descriptor.getParent().resolve(text(list(root.get("entry_parts")).get(0)));var fragment=json(part);Object entries=fragment.get("entries");var changed=object(list(entries).get(0));changed.put("value",value);replace(entries,0,changed);save(part,fragment);if(coherent){Path mtx=descriptor.resolveSibling(descriptor.getFileName().toString().replaceFirst("[.]json$",".mtx"));var lines=new ArrayList<>(Files.readAllLines(mtx,StandardCharsets.UTF_8));String[] f=lines.get(2).split(" ");f[2]=value;lines.set(2,String.join(" ",f));Files.write(mtx,lines,StandardCharsets.UTF_8);}}
    @ParameterizedTest(name="constructed:{0}") @MethodSource("versions") void auditsEveryOriginalConstructedCoordinateAndProfile(String version)throws IOException{Context c=contexts.get(version);SoupXWorkflowAudit.constructed(c.root.resolve("worker"),c.population,c.request,meter(c));}
    @ParameterizedTest(name="{0}") @MethodSource("cases") void auditsEveryOriginalCaseWithoutExecutingR(Case test)throws IOException{Context c=contexts.get(test.version);var result=audit(c,c.root.resolve("worker/cases").resolve(test.id),test.id);assertEquals(test.id,result.get("id"));assertEquals(false,result.get("automatic_estimator_or_count_correction_independently_refitted"));if(test.id.startsWith("manual-"))assertNotEquals(0.0,((Number)result.get("original_minus_analytical")).doubleValue());}
    @Test void coherentConstructedCountChangeIsRejected()throws IOException{Context c=contexts.get("1.6.2");Path worker=workerCopy("1.6.2");sparseChange(worker.resolve("constructed-raw.json"),"999999",true);IOException failure=assertThrows(IOException.class,()->SoupXWorkflowAudit.constructed(worker,c.population,c.request,meter(c)));assertTrue(failure.getMessage().contains("Original constructed count value differs"));}
    @Test void coherentCorrectedCountInflationIsRejected()throws IOException{Context c=contexts.get("1.6.2");Path target=caseCopy("1.6.2","fixed-constant");sparseChange(target.resolve("corrected-counts.json"),"999999",true);IOException failure=assertThrows(IOException.class,()->audit(c,target,"fixed-constant"));assertTrue(failure.getMessage().contains("Original corrected value outside its observed count"));}
    @Test void coherentMaskFlipIsRejected()throws IOException{Context c=contexts.get("1.6.2");Path target=caseCopy("1.6.2","manual-provided");tableChange(target.resolve("nonexpression-mask.json"),"CD7",0,"TRUE",null);assertThrows(IOException.class,()->audit(c,target,"manual-provided"));}
    @Test void coherentAutomaticExposureChangeIsRejected()throws IOException{Context c=contexts.get("1.6.2");Path target=caseCopy("1.6.2","auto-estimate");tableChange(target.resolve("auto-estimates.json"),"expCnt",0,"999999",null);assertThrows(IOException.class,()->audit(c,target,"auto-estimate"));}
    @Test void coherentFixedRhoChangeIsRejected()throws IOException{Context c=contexts.get("1.6.2");Path target=caseCopy("1.6.2","fixed-constant");tableChange(target.resolve("metadata.json"),"rho",0,"0.2",null);assertThrows(IOException.class,()->audit(c,target,"fixed-constant"));}
    @Test void analyticalMleCannotReplaceOriginalGlmValue()throws IOException{Context c=contexts.get("1.6.2");String id="manual-provided";Path target=caseCopy("1.6.2",id);var original=audit(c,c.root.resolve("worker/cases").resolve(id),id);tableChange(target.resolve("metadata.json"),"rho",0,original.get("analytical_Poisson_rho_diagnostic").toString(),null);assertThrows(IOException.class,()->audit(c,target,id));}
    @Test void undeclaredRngSeedIsRejected()throws IOException{Context c=contexts.get("1.6.2");Path target=caseCopy("1.6.2","fixed-constant");Path path=target.resolve("source-status.json");var state=json(path);state.put("seed",7);save(path,state);assertThrows(IOException.class,()->audit(c,target,"fixed-constant"));}
    @Test void MatrixMarketAndJsonMustAgreeExactly()throws IOException{Context c=contexts.get("1.6.2");Path target=caseCopy("1.6.2","fixed-constant");sparseChange(target.resolve("corrected-counts.json"),"999999",false);IOException failure=assertThrows(IOException.class,()->audit(c,target,"fixed-constant"));assertTrue(failure.getMessage().contains("Matrix Market/JSON coordinate differs"));}
    @Test void coherentNonfiniteProfileIsRejected()throws IOException{Context c=contexts.get("1.6.2");Path worker=workerCopy("1.6.2");tableChange(worker.resolve("soup-profile.json"),"est",0,"NaN","NaN");assertThrows(IOException.class,()->SoupXWorkflowAudit.constructed(worker,c.population,c.request,meter(c)));}
    Path inputCopy()throws IOException{Path target=temporary.resolve("inputs");copy(contexts.get("1.6.2").root.resolve("inputs"),target);return target;}
    @Test void duplicateSparseInputCoordinatesAreNotSummed()throws IOException{Context c=contexts.get("1.6.2");Path inputs=inputCopy(),path=inputs.resolve("raw-counts");var lines=new ArrayList<>(Files.readAllLines(path));int dimensions=2;String[] f=lines.get(dimensions).split(" ");f[2]=Long.toString(Long.parseLong(f[2])+1);lines.set(dimensions,String.join(" ",f));lines.add(lines.get(dimensions+1));Files.write(path,lines);assertThrows(IllegalArgumentException.class,()->SoupXWorkflowInputs.validate(inputs,c.request,new SoupXAmbient.Budget(c.request.auditOperations())));}
    @Test void nearIntegerFractionIsNotRoundedIntoACount()throws IOException{Context c=contexts.get("1.6.2");Path inputs=inputCopy(),path=inputs.resolve("raw-counts");var lines=new ArrayList<>(Files.readAllLines(path));String[] f=lines.get(3).split(" ");f[2]="9007199254740991.1";lines.set(3,String.join(" ",f));Files.write(path,lines);assertThrows(IOException.class,()->SoupXWorkflowInputs.validate(inputs,c.request,new SoupXAmbient.Budget(c.request.auditOperations())));}
    @Test void firstLiteralFalseCannotSilentlyDisableDeclaredClusterCorrection()throws IOException{Context c=contexts.get("1.6.2");Path inputs=inputCopy(),path=inputs.resolve("cells.tsv");var lines=new ArrayList<>(Files.readAllLines(path));String[] first=lines.get(1).split("\t",-1);first[1]="FALSE";lines.set(1,String.join("\t",first));Files.write(path,lines);var raw=json(c.root.resolve("source-request.json"));var firstCase=object(list(raw.get("analyses")).get(0));var adjustment=object(firstCase.get("adjustment"));adjustment.put("clustering_scope","supplied-clusters");firstCase.put("adjustment",adjustment);replace(raw.get("analyses"),0,firstCase);var r=SoupXWorkflowRequest.parse(raw,c.root);IOException failure=assertThrows(IOException.class,()->SoupXWorkflowInputs.validate(inputs,r,new SoupXAmbient.Budget(r.auditOperations())));assertTrue(failure.getMessage().contains("First literal cluster FALSE"));}
    @Test void missingPinnedSourceSkipsDependentExecution()throws IOException{Context c=contexts.get("1.6.2");var r=request(c.root,Map.of("soup_source",temporary.resolve("absent-source").toString()));Path stage=temporary.resolve("stage");Files.createDirectory(stage);assertThrows(SoupXWorkflowRuntime.Unavailable.class,()->SoupXWorkflowRuntime.sources(stage,r,false));assertFalse(Files.exists(stage.resolve("worker")));}
    @Test void missingRuntimeSkipsWithoutStartingAProcess()throws IOException{Context c=contexts.get("1.6.2");var r=request(c.root,Map.of("r_home",temporary.resolve("absent-R-home").toString()));Path stage=temporary.resolve("stage");Files.createDirectories(stage.resolve("worker"));assertThrows(SoupXWorkflowRuntime.Unavailable.class,()->SoupXWorkflowRuntime.run(stage,r,new LinkedHashMap<>()));assertFalse(Files.exists(stage.resolve("worker/process-receipt.json")));}
    @Test void multilineUpstreamDiagnosticIsPreservedVerbatim()throws IOException{Context c=contexts.get("1.3.0");Path target=c.root.resolve("worker/cases/fixed-constant");var original=list(json(target.resolve("source-status.json")).get("messages"));assertTrue(original.stream().anyMatch(v->v.toString().contains("\n")));assertEquals(original,audit(c,target,"fixed-constant").get("original_messages"));}
    @Test void auditWorkCapacityRefusesCompleteAdmission()throws IOException{Context c=contexts.get("1.6.2");assertThrows(IOException.class,()->SoupXWorkflowAudit.constructed(c.root.resolve("worker"),c.population,c.request,new SoupXWorkflowTransport.Meter(1)));}
}
